// 暂不可用不消耗工时；死亡/组织解散仅停止未完劳动，保已做历史与待清算责任。
#include "governance_task_step.hpp"
#include "task_public_account_context.hpp"
#include "task_public_account_phase.hpp"
#include <limits>
namespace hanmo::resident {
Outcome<GovernanceTaskStep> step_governance_task_action(CommonStore& common,TaskState& tasks,GovernanceTaskState& governance,const GovernanceAuthorityRead& authority,const StableId& action_id,Integer to_tick,const GovernanceOutcomeFreeze& freeze,const GovernanceReleaseResources& release,const TaskExecutionServices* execution){
    GovernanceTaskContract* contract=nullptr;for(auto& row:governance.governance_contracts.rows())if(row.second.action_id==action_id){if(contract)return {false,{},common_failure("DuplicateGovernanceAction",action_id,ErrorKind::internal).error};contract=&row.second;}
    if(!contract)return {false,{},common_failure("UnknownGovernanceAction",action_id).error};const auto& accepted=contract->acceptance;GovernanceTaskRead read(common,tasks,governance);auto source=read.governance_task_source(accepted.task_id);if(!source.ok)return {false,{},source.error};
    const auto* current=common.action(action_id);if(!current||source.value.task_status!="active"||source.value.work||source.value.completion||source.value.interruption||current->kind!="governance_appease"||current->actor_id!=accepted.executor_actor_id||current->participants!=std::vector<StableId>{accepted.executor_actor_id}||current->remaining_ticks<1||current->remaining_ticks>accepted.work_ticks||current->start_tick<accepted.accepted_tick||common.tick()==std::numeric_limits<Integer>::max()||to_tick!=common.tick()+1)return {false,{},common_failure("InvalidGovernanceWorkStep",action_id,ErrorKind::internal).error};
    // 接管只改变同一救济契约的执行权源；原工时、执行人及终态记录保持唯一。
    auto context=validate_task_execution_services(tasks,execution);if(!context.ok)return {false,{},context.error};
    if(execution){auto observed=task_public_account_observed_tick(common,execution->phase);if(!observed.ok)return {false,{},observed.error};if(observed.value!=to_tick)return {false,{},common_failure("TaskTakeoverPhaseMismatch").error};}
    const auto action=*current;auto continuity=execution?authority.governance_relief_continuity(accepted.authority_source_fact_id,accepted.executor_actor_id,accepted.contract_id,*execution->politics):authority.governance_continuity(accepted.authority_source_fact_id,accepted.executor_actor_id);if(!continuity.ok)return {false,{},continuity.error};const auto& decision=continuity.value;GovernanceTaskStep result;result.task_id=accepted.task_id;
    if(decision.kind==GovernanceContinuityKind::pause_executor||decision.kind==GovernanceContinuityKind::needs_reassignment){result.suspended=true;result.code=decision.code.empty()?(decision.kind==GovernanceContinuityKind::pause_executor?"ExecutorUnavailable":"NeedsReassignment"):decision.code;contract->execution_note_code=result.code;return {true,std::move(result),{}};}
    if(decision.kind==GovernanceContinuityKind::terminate_executor_dead||decision.kind==GovernanceContinuityKind::terminate_principal_dissolved){
        if(!release)return {false,{},common_failure("MissingGovernanceReleaseService",action_id,ErrorKind::internal).error};const auto* actor=common.actor(accepted.executor_actor_id);if(decision.kind==GovernanceContinuityKind::terminate_executor_dead&&(!actor||actor->alive))return {false,{},common_failure("GovernanceDeathSourceMismatch",action_id,ErrorKind::internal).error};
        auto freed=release(read,source.value);if(!freed.ok)return {false,{},freed.error};auto id=common.next_id("governance_interruption");if(!id.ok)return {false,{},id.error};GovernanceWorkInterruption interruption;interruption.fact_id=id.value;interruption.task_id=accepted.task_id;interruption.contract_id=accepted.contract_id;interruption.action_id=action_id;interruption.acceptance_fact_id=accepted.fact_id;interruption.reason=decision.kind==GovernanceContinuityKind::terminate_executor_dead?"ExecutorDead":"PrincipalDissolved";interruption.stopped_tick=to_tick;interruption.completed_work_ticks=accepted.work_ticks-action.remaining_ticks;
        if(decision.source_fact_id){if(decision.source_fact_id->empty()||!common.state().facts.find(*decision.source_fact_id))return {false,{},common_failure("MissingGovernanceInterruptionCause",action_id,ErrorKind::internal).error};interruption.cause_fact_id=decision.source_fact_id;}
        auto appended=common.append_fact({id.value,"governance_work_interrupted","tasks"});if(!appended.ok)return {false,{},appended.error};contract->interruption=interruption;contract->execution_note_code.clear();contract->pending_code=interruption.reason;tasks.tasks.find(accepted.task_id)->status="settling";result.action_finished=true;result.success=false;result.code=interruption.reason;result.fact_id=id.value;return {true,std::move(result),{}};
    }
    if(decision.kind!=GovernanceContinuityKind::continue_work)return {false,{},common_failure("UnknownGovernanceContinuity",action_id,ErrorKind::internal).error};
    const auto* actor=common.actor(accepted.executor_actor_id);if(!actor||!actor->alive||!actor->available)return {false,{},common_failure("GovernanceExecutorContinuityMismatch",action_id,ErrorKind::internal).error};
    contract->execution_note_code.clear();ActionMutation decrement;decrement.action=action;decrement.remaining_ticks=action.remaining_ticks-1;auto advanced=common.apply_action(decrement);if(!advanced.ok)return {false,{},advanced.error};if(action.remaining_ticks>1)return {true,std::move(result),{}};
    auto work=finish_governance_work(common,tasks,governance,action_id,to_tick,freeze);if(!work.ok)return {false,{},work.error};result.action_finished=true;result.fact_id=work.value.fact_id;return {true,std::move(result),{}};
}
}
